// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(this));
        vm.assume(actor != address(c));

        address oldOwner = c.owner();

        vm.prank(actor);
        try c.setOwner(actor) {
            // non-admin must not be able to change owner
            assertTrue(c.owner() == oldOwner, "non-admin changed owner");
        } catch {
            // reverting is also fine: owner unchanged
            assertTrue(c.owner() == oldOwner, "owner changed on revert");
        }
    }
}
